  // reversing the script gives deletion-first ordering within each region.
  function flushChanges() {
    for (const line of inserts) script.push({ op: 'insert', line });
    for (const line of deletes) script.push({ op: 'delete', line });
    inserts.length = 0;
    deletes.length = 0;
  }

  let x = a.length;
  let y = b.length;
  for (let d = trace.length - 1; d > 0; d--) {
    const previous = trace[d - 1];
    const j = (x - y + d) / 2;
    const insertion = j === 0 || (j < d && previous[j - 1] < previous[j]);
    const previousIndex = insertion ? j : j - 1;
    const previousX = previous[previousIndex];
    const previousY = previousX - (2 * previousIndex - (d - 1));
    if (x > previousX && y > previousY) {
      flushChanges();
      while (x > previousX && y > previousY) {
        script.push({ op: 'equal', line: a[--x] });
        y--;
      }
    }
    if (insertion) {
      inserts.push(b[--y]);
    } else {
      deletes.push(a[--x]);
    }
