  let index = 0;
  let oldPosition = 0;
  let newPosition = 0;

  while (index < script.length) {
    if (script[index].op === 'equal') {
      index++;
      oldPosition++;
      newPosition++;
      continue;
    }

    const start = Math.max(0, index - context);
    const oldBefore = oldPosition - (index - start);
    const newBefore = newPosition - (index - start);
    let lastChange = index;
    for (let scan = index + 1; scan < script.length; scan++) {
      if (script[scan].op !== 'equal') {
        lastChange = scan;
      } else if (scan - lastChange > 2 * context) {
        break;
      }
    }
    const end = Math.min(script.length, lastChange + context + 1);
    const lines = [];
    let oldLines = 0;
    let newLines = 0;
    for (let i = start; i < end; i++) {
      const { op, line } = script[i];
      if (op !== 'insert') oldLines++;
      if (op !== 'delete') newLines++;
      lines.push((op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line);
    }
    hunks.push({
      oldStart: oldBefore + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newBefore + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
    oldPosition = oldBefore + oldLines;
    newPosition = newBefore + newLines;
    index = end;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let consumed = 0;
  for (let index = 0; index < hunks.length; index++) {
    const hunk = hunks[index];
    const fail = () => {
      throw new Error(`hunk ${index} does not apply`);
    };
    if (hunk === null || typeof hunk !== 'object' || !Array.isArray(hunk.lines)) {
      fail();
    }
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!Number.isSafeInteger(oldStart) || oldStart < 0 ||
        !Number.isSafeInteger(newStart) || newStart < 0 ||
        !Number.isSafeInteger(oldLines) || oldLines < 0 ||
        !Number.isSafeInteger(newLines) || newLines < 0) {
      fail();
    }
    const oldIndex = oldStart - (oldLines === 0 ? 0 : 1);
    const newIndex = newStart - (newLines === 0 ? 0 : 1);
    if (oldIndex < consumed || oldIndex > a.length ||
        oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - consumed) {
      fail();
    }

    for (; consumed < oldIndex; consumed++) result.push(a[consumed]);
    let oldCount = 0;
    let newCount = 0;
    for (const entry of lines) {
      if (typeof entry !== 'string' || entry.length === 0) fail();
      const prefix = entry[0];
      const line = entry.slice(1);
      if (prefix === ' ' || prefix === '-') {
        if (oldCount >= oldLines || a[consumed] !== line) fail();
        consumed++;
        oldCount++;
      } else if (prefix !== '+') {
        fail();
      }
      if (prefix === ' ' || prefix === '+') {
        result.push(line);
        newCount++;
      }
    }
    if (oldCount !== oldLines || newCount !== newLines) fail();
  }
  for (; consumed < a.length; consumed++) result.push(a[consumed]);
