      arrays.push(Array.from({ length }, (_, i) => bits & (1 << i) ? 'x' : ''));
    }
  }
  for (const a of arrays) {
    Object.freeze(a);
    for (const b of arrays) {
      Object.freeze(b);
      checkScript(a, b);
      for (const context of [0, 1, 2, 3, 10]) {
        const hunks = unifiedHunks(a, b, { context });
        for (const hunk of hunks) {
          Object.freeze(hunk.lines);
          Object.freeze(hunk);
        }
        Object.freeze(hunks);
        assert.deepEqual(applyHunks(a, hunks), b);
        if (a.length === b.length && a.every((line, i) => line === b[i])) assert.deepEqual(hunks, []);
      }
    }
  }
});

test('unified coordinates at top, bottom, empty ranges, and shifted later hunks', () => {
  assert.deepEqual(unifiedHunks([], ['+first', ''], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 2, lines: ['++first', '+'] },
  ]);
  assert.deepEqual(unifiedHunks(['-first', ''], [], { context: 0 }), [
    { oldStart: 1, oldLines: 2, newStart: 0, newLines: 0, lines: ['--first', '-'] },
  ]);
  assert.deepEqual(unifiedHunks(['a'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+b'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a'], { context: 0 }), [
    { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-b'] },
  ]);
  const a = ['a', 'b', 'c', 'd'];
  const b = ['top', 'a', 'b', 'c', 'tail'];
  const hunks = unifiedHunks(a, b, { context: 0 });
  assert.deepEqual(hunks, [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] },
    { oldStart: 4, oldLines: 1, newStart: 5, newLines: 1, lines: ['-d', '+tail'] },
  ]);
  assert.deepEqual(applyHunks(a, hunks), b);
  const deletionFirst = unifiedHunks(['gone', 'a', 'b', 'c'], ['a', 'b', 'c', 'tail'], { context: 0 });
  assert.deepEqual(deletionFirst, [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-gone'] },
    { oldStart: 4, oldLines: 0, newStart: 4, newLines: 1, lines: ['+tail'] },
  ]);
  assert.deepEqual(applyHunks(['gone', 'a', 'b', 'c'], deletionFirst), ['a', 'b', 'c', 'tail']);
});

test('context merges touching regions once and separates larger gaps', () => {
  assert.deepEqual(unifiedHunks(['a', 'old1', 'b', 'c', 'old2', 'd'], ['a', 'new1', 'b', 'c', 'new2', 'd'], { context: 1 }), [
    { oldStart: 1, oldLines: 6, newStart: 1, newLines: 6,
      lines: [' a', '-old1', '+new1', ' b', ' c', '-old2', '+new2', ' d'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'old1', 'b', 'c', 'd', 'old2', 'e'], ['a', 'new1', 'b', 'c', 'd', 'new2', 'e'], { context: 1 }), [
    { oldStart: 1, oldLines: 3, newStart: 1, newLines: 3, lines: [' a', '-old1', '+new1', ' b'] },
    { oldStart: 5, oldLines: 3, newStart: 5, newLines: 3, lines: [' d', '-old2', '+new2', ' e'] },
  ]);
  const a = ['+keep', '-old', ' space', '', '+tail'];
  const b = ['+keep', '+new', ' space', '', '+tail'];
  assert.deepEqual(unifiedHunks(a, b), [{ oldStart: 1, oldLines: 5, newStart: 1, newLines: 5,
    lines: [' +keep', '--old', '++new', '  space', ' ', ' +tail'] }]);
  assert.deepEqual(applyHunks(a, unifiedHunks(a, b)), b);
});

test('applying hunks rejects malformed fields, content, overlap and inconsistent coordinates', () => {
  const a = Object.freeze(['a', 'b', 'c']);
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const bad = [null, undefined, {}, { ...valid, lines: 'bad' },
    ...['oldStart', 'oldLines', 'newStart', 'newLines'].flatMap(field =>
      [-1, 1.5, NaN, Infinity, '1', undefined].map(value => ({ ...valid, [field]: value }))),
    { ...valid, oldStart: 0 }, { ...valid, oldStart: 5 }, { ...valid, newStart: 0 },
    { ...valid, newStart: 3 }, { ...valid, oldLines: 0 }, { ...valid, oldLines: 2 },
    { ...valid, newLines: 0 }, { ...valid, newLines: 2 },
    { ...valid, lines: ['-wrong', '+B'] }, { ...valid, lines: [' wrong'] },
    { ...valid, lines: ['', '+B'] }, { ...valid, lines: [null] },
    { ...valid, lines: ['?b', '+B'] }, { ...valid, lines: ['-b', '-c', '+B'] },
  ];
  for (const hunk of bad) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: [' a'] }]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] }, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [{ oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: [' a', ' wrong'] }]), /hunk 0 does not apply/);
  const copy = applyHunks(a, []);
  assert.deepEqual(copy, a);
  assert.notEqual(copy, a);
});

test('20,000-line small changes remain well below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? String(i % 3) : `line ${i}`);
    const b = a.slice();
    b.splice(19000, 1);
    b.splice(10000, 1, 'replacement');
    b.splice(100, 0, '+inserted', '');
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const patched = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(patched, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 5);
    assert.ok(elapsed < 1000, `${elapsed}ms`);
    console.log(`20,000 lines (${repetitive ? 'repetitive' : 'unique'}): ${elapsed.toFixed(1)}ms including diff, hunks and application`);
  }
});
